<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('customers.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT * FROM customers WHERE id=?');$s->execute([$id]);$customer=$s->fetch();if(!$customer){http_response_code(404);exit('Customer not found');}
$s=$db->prepare('SELECT s.*,u.display_name cashier,(SELECT GROUP_CONCAT(CONCAT(p.name," x ",si.quantity) SEPARATOR ", ") FROM sale_items si JOIN products p ON p.id=si.product_id WHERE si.sale_id=s.id) items FROM sales s JOIN users u ON u.id=s.created_by WHERE s.customer_id=? ORDER BY s.sale_date DESC,s.id DESC');$s->execute([$id]);$sales=$s->fetchAll();$s=$db->prepare('SELECT p.*,u.display_name collector FROM customer_payments p JOIN users u ON u.id=p.collected_by WHERE p.customer_id=? ORDER BY p.payment_date DESC,p.id DESC');$s->execute([$id]);$payments=$s->fetchAll();
$s=$db->prepare('SELECT entry_date,reference,description,debit,credit FROM (SELECT o.opening_date entry_date,CONCAT("OPEN-",o.id) reference,"Opening credit balance" description,o.amount debit,0 credit,o.id sort_id FROM customer_opening_balances o WHERE o.customer_id=? UNION ALL SELECT s.sale_date,s.sale_no,CONCAT(UPPER(s.sale_type)," credit sale"),s.total,0,s.id FROM sales s WHERE s.customer_id=? AND s.payment_type="credit" AND s.status NOT IN("cancelled","returned") UNION ALL SELECT s.sale_date,CONCAT(s.sale_no,"-INITIAL"),"Initial payment on credit invoice",0,sp.amount,sp.id FROM sale_payments sp JOIN sales s ON s.id=sp.sale_id WHERE s.customer_id=? AND s.payment_type="credit" UNION ALL SELECT p.payment_date,p.receipt_no,"Customer payment",0,p.amount,p.id FROM customer_payments p WHERE p.customer_id=?) ledger ORDER BY entry_date,sort_id');$s->execute([$id,$id,$id,$id]);$ledger=$s->fetchAll();$balance=0;foreach($ledger as &$entry){$balance+=(float)$entry['debit']-(float)$entry['credit'];$entry['running_balance']=$balance;}unset($entry);$totalSales=array_sum(array_map(fn($r)=>(float)$r['total'],$sales));$cashSales=array_sum(array_map(fn($r)=>$r['payment_type']==='cash'?(float)$r['total']:0,$sales));$creditSales=array_sum(array_map(fn($r)=>$r['payment_type']==='credit'?(float)$r['total']:0,$sales));page_start('Customer Account','customers.php');?>
<div class="account-actions"><a class="btn secondary" href="customers.php">← Customers</a><button class="btn secondary" onclick="window.print()">Print Statement</button></div><section class="account-head panel"><div><span class="eyebrow">Customer account</span><h2><?=e($customer['name'])?></h2><p><?=e($customer['customer_code'])?> · <?=e($customer['phone']?:'No phone')?> · <?=e($customer['business_name']?:'')?></p><p><?=e($customer['address']?:'')?></p></div><div class="credit-state <?=$customer['credit_enabled']?'enabled':'disabled'?>"><span>Credit Account</span><b><?=$customer['credit_enabled']?'Enabled':'Not Enabled'?></b><small><?=e(str_replace('_',' ',$customer['default_payment_period']))?></small></div></section><section class="kpi-grid account-kpis"><article class="kpi"><span>All Purchases</span><strong><?=money($totalSales)?></strong><small><?=count($sales)?> invoice(s)</small></article><article class="kpi"><span>Cash Purchases</span><strong><?=money($cashSales)?></strong></article><article class="kpi"><span>Credit Purchases</span><strong><?=money($creditSales)?></strong></article><article class="kpi balance-card"><span>Currently Owes</span><strong><?=money($customer['outstanding'])?></strong><small>Live customer balance</small></article></section><section class="account-tabs"><button class="active" data-tab="sales">All Invoices</button><button data-tab="ledger">Credit Ledger</button><button data-tab="payments">Payment Receipts</button></section><section class="panel table-panel account-section active" id="sales"><div class="panel-head"><div><span class="eyebrow">Complete purchase history</span><h3>Cash and credit invoices</h3></div></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Date</th><th>Items Purchased</th><th>Type</th><th>Status</th><th class="right">Total</th><th class="right">Paid</th><th class="right">Due</th><th></th></tr></thead><tbody><?php if(!$sales):?><tr><td colspan="9"><div class="empty-state compact"><b>No purchases yet</b></div></td></tr><?php endif;?><?php foreach($sales as $r):?><tr><td><b><?=e($r['sale_no'])?></b></td><td><?=date('d M Y, H:i',strtotime($r['sale_date']))?></td><td class="wrap-cell"><?=e($r['items']?:'—')?></td><td><span class="tag"><?=e($r['sale_type'].' / '.$r['payment_type'])?></span></td><td><span class="status status-<?=e($r['status'])?>"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></span></td><td class="right"><?=money($r['total'])?></td><td class="right"><?=money($r['paid_amount'])?></td><td class="right"><b><?=money($r['balance'])?></b></td><td><a href="sale_view.php?id=<?=$r['id']?>">View</a></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel table-panel account-section" id="ledger"><div class="panel-head"><div><span class="eyebrow">Account statement</span><h3>Credit ledger with running balance</h3></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Reference</th><th>Description</th><th class="right">Added to Debt</th><th class="right">Payment</th><th class="right">Balance</th></tr></thead><tbody><?php if(!$ledger):?><tr><td colspan="6"><div class="empty-state compact"><b>No credit activity</b></div></td></tr><?php endif;?><?php foreach($ledger as $r):?><tr><td><?=date('d M Y',strtotime($r['entry_date']))?></td><td><b><?=e($r['reference'])?></b></td><td><?=e($r['description'])?></td><td class="right"><?=money($r['debit'])?></td><td class="right"><?=money($r['credit'])?></td><td class="right"><b><?=money($r['running_balance'])?></b></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="5">Current Account Balance</th><th class="right"><?=money($customer['outstanding'])?></th></tr></tfoot></table></div></section><section class="panel table-panel account-section" id="payments"><div class="panel-head"><div><span class="eyebrow">Money received</span><h3>Payment receipts</h3></div></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Date</th><th>Method</th><th>Reference</th><th>Collected By</th><th class="right">Amount</th></tr></thead><tbody><?php if(!$payments):?><tr><td colspan="6"><div class="empty-state compact"><b>No separate credit payments yet</b></div></td></tr><?php endif;?><?php foreach($payments as $r):?><tr><td><b><?=e($r['receipt_no'])?></b></td><td><?=date('d M Y, H:i',strtotime($r['payment_date']))?></td><td><?=e(str_replace('_',' ',$r['method']))?></td><td><?=e($r['reference_no']?:'—')?></td><td><?=e($r['collector'])?></td><td class="right"><b><?=money($r['amount'])?></b></td></tr><?php endforeach;?></tbody></table></div></section><style>.account-actions{display:flex;justify-content:space-between;margin-bottom:15px}.account-head{display:flex;justify-content:space-between;gap:20px}.account-head h2{font-size:28px;margin:7px 0}.account-head p{color:#718078;margin:4px 0}.credit-state{min-width:190px;padding:16px;border-radius:12px;display:flex;flex-direction:column}.credit-state.enabled{background:#e2f3e8;color:#17683b}.credit-state.disabled{background:#f1f2ef;color:#666}.credit-state span,.credit-state small{font-size:11px}.credit-state b{font-size:18px;margin:5px 0}.account-kpis{margin-top:18px}.balance-card{border-top:4px solid #d14b43}.account-tabs{display:flex;gap:8px;margin:20px 0 10px}.account-tabs button{border:1px solid #dfe5df;background:#fff;padding:11px 16px;border-radius:9px;font-weight:700}.account-tabs button.active{background:#174e39;color:#fff}.account-section{display:none}.account-section.active{display:block}.wrap-cell{white-space:normal;min-width:240px}@media(max-width:700px){.account-head{flex-direction:column}.account-tabs{overflow:auto}}@media print{.sidebar,.topbar,.account-actions,.account-tabs,#sales,#payments{display:none!important}.app{margin:0!important;width:100%!important}.content{padding:0!important}#ledger{display:block!important}}</style><script>document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.account-section').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('#'+b.dataset.tab).classList.add('active')});</script><?php page_end();
